INSERT INTO concepts (id, lesson_id, concept_text, key_points, order_index, created_at, updated_at) VALUES
('e4b5f6a7-8901-23de-fabc-4567890abcde', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Laptop Internal Hardware Components - Laptops use specialized compact components optimized for mobility, power efficiency, and thermal management. Understanding these components is crucial for troubleshooting and upgrades.', ARRAY['SODIMM RAM modules are smaller than desktop DIMM, typically 204-pin (DDR4) or 260-pin (DDR5)', 'Storage options include 2.5" SATA drives, M.2 SATA, and M.2 NVMe SSDs', 'Mobile CPUs are designed for lower power consumption and heat generation', 'Mini-PCIe and M.2 slots accommodate wireless cards and other expansion modules', 'Cooling systems use heat pipes and compact fans due to space constraints', 'Most components are integrated or soldered, limiting upgrade options'], 8, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('f5c6a7b8-9012-34ef-abcd-567890abcdef', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Laptop Display Technologies - Modern laptops use various display technologies, each with distinct characteristics affecting image quality, power consumption, and cost.', ARRAY['LCD (Liquid Crystal Display) is most common, requiring backlighting', 'LED backlighting has replaced CCFL in modern laptops for better efficiency', 'OLED displays provide superior contrast ratios and don''t require backlighting', 'TN panels offer fast response times but limited viewing angles', 'IPS panels provide better color accuracy and wider viewing angles', 'Common resolutions: HD (1366x768), FHD (1920x1080), QHD (2560x1440), 4K (3840x2160)', 'Touch capability requires additional digitizer layer', 'Matte vs. glossy finishes affect glare and color vibrancy'], 9, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('a6d7b8c9-0123-45fa-bcde-67890abcdef1', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Laptop Input Devices and Features - Laptops integrate various input methods and features designed for portable computing and user convenience.', ARRAY['Touchpad (trackpad) with multi-touch gesture support replaces external mouse', 'TrackPoint (pointing stick) found on some business laptops', 'Function (Fn) key provides access to hardware controls and shortcuts', 'Common Fn combinations: brightness, volume, Wi-Fi toggle, external display', 'Built-in keyboard often has different key layouts (compact, chicklet style)', 'Some keys may require Fn key to access (F1-F12 functions)', 'Biometric features: fingerprint readers, facial recognition cameras', 'Ambient light sensors automatically adjust screen brightness'], 10, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('b7c8d9e0-1234-56ef-bcde-78901abcdef2', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Laptop Connectivity and Expansion - Understanding laptop connectivity options and expansion methods is essential for supporting users and troubleshooting connectivity issues.', ARRAY['Docking stations provide multiple ports through single connection (USB-C, proprietary)', 'Port replicators add ports but typically don''t provide power', 'Common ports: USB-A, USB-C, HDMI, 3.5mm audio, SD card reader', 'Legacy ports may include VGA, Ethernet, or serial connections', 'USB-C can support power delivery, video output, and data transfer', 'Thunderbolt provides high-speed data transfer and display connectivity', 'ExpressCard slots (legacy) for expansion cards', 'Some laptops support eGPU (external graphics) via Thunderbolt'], 11, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('c8d9e0f1-2345-67fa-cdef-89012abcdef3', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Laptop Power Management - Power management is critical for laptop operation, affecting battery life and thermal performance.', ARRAY['Battery types: Lithium-ion (Li-ion) and Lithium-polymer (Li-Po)', 'Power adapters convert AC to DC power for charging and operation', 'Power management settings control CPU performance and power consumption', 'Sleep, hibernate, and hybrid sleep modes conserve battery power', 'Thermal throttling reduces performance to prevent overheating', 'Power delivery via USB-C allows single-cable charging and data', 'Battery calibration helps maintain accurate charge level reporting'], 12, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('d9e0f1a2-3456-78ab-def0-90123abcdef4', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Laptop Wireless Technologies - Modern laptops include various wireless communication technologies for connectivity and data transfer.', ARRAY['Wi-Fi standards: 802.11ac (Wi-Fi 5), 802.11ax (Wi-Fi 6), 802.11be (Wi-Fi 7)', 'Bluetooth for short-range device connectivity (keyboards, mice, headphones)', 'Near Field Communication (NFC) for contactless data exchange', 'Cellular connectivity (LTE, 5G) in some business/premium models', 'Wireless cards typically use M.2 or Mini-PCIe form factors', 'Antenna placement affects signal quality and requires careful routing', 'Flight mode disables all wireless radios simultaneously'], 13, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z');

-- Insert Questions/MCQs (order 14-25)
INSERT INTO questions (id, lesson_id, question_text, options, correct_answer, explanation, order_index, created_at, updated_at) VALUES
('b7e8c9d0-1234-56ab-cdef-7890abcdef12', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'What type of RAM is most commonly used in laptops?', '["DIMM", "SODIMM", "RIMM", "SIMM"]', 1, 'SODIMM (Small Outline DIMM) is the compact RAM form factor designed specifically for laptops and small form factor computers.', 14, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('c8f9d0e1-2345-67bc-def0-890abcdef123', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Which display technology provides the best contrast ratio and true blacks?', '["TN LCD", "IPS LCD", "OLED", "VA LCD"]', 2, 'OLED displays can turn off individual pixels completely, providing infinite contrast ratios and true blacks, unlike LCD technologies that require backlighting.', 15, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('d9a0e1f2-3456-78cd-ef01-90abcdef1234', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'A user reports their laptop screen is very dim but still visible. What component is most likely failing?', '["LCD panel", "Graphics card", "Inverter or backlight", "Digitizer"]', 2, 'A dim but visible screen typically indicates a failing backlight or inverter (in older CCFL displays), as the LCD panel itself is still functioning.', 16, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('e0a1f2b3-4567-89de-f012-1abcdef23456', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Which storage interface provides the fastest data transfer speeds in modern laptops?', '["SATA III", "M.2 SATA", "M.2 NVMe", "eMMC"]', 2, 'M.2 NVMe SSDs use PCIe lanes for data transfer, providing much faster speeds than SATA-based storage solutions.', 17, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('f1b2a3c4-5678-90ef-0123-2abcdef34567', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'What is the primary difference between a docking station and a port replicator?', '["Number of available ports", "Connection interface type", "Power delivery capability", "Physical size"]', 2, 'Docking stations typically provide power to the laptop while expanding connectivity, whereas port replicators usually only add ports without power delivery.', 18, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('a2c3b4d5-6789-01fa-1234-3abcdef45678', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'A touchscreen laptop is not responding to touch input, but the display works normally. Which component is most likely defective?', '["LCD panel", "Graphics driver", "Digitizer", "Inverter"]', 2, 'The digitizer is responsible for converting touch input to digital signals. A failed digitizer will prevent touch functionality while leaving display capability intact.', 19, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('b3d4c5e6-7890-12ab-2345-4abcdef56789', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Which wireless standard is also known as Wi-Fi 6?', '["802.11n", "802.11ac", "802.11ax", "802.11be"]', 2, '802.11ax is the technical designation for Wi-Fi 6, which offers improved performance and efficiency over previous Wi-Fi standards.', 20, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('c4e5d6f7-8901-23bc-3456-5abcdef67890', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'When a laptop''s CPU temperature becomes too high, what automatic response typically occurs?', '["System shutdown", "Thermal throttling", "Fan failure", "Battery discharge"]', 1, 'Thermal throttling automatically reduces CPU performance to lower heat generation and prevent damage when temperatures exceed safe thresholds.', 21, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('d5f6e7a8-9012-34cd-4567-6abcdef78901', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Which laptop feature automatically adjusts screen brightness based on surrounding light conditions?', '["Digitizer", "Gyroscope", "Ambient light sensor", "Proximity sensor"]', 2, 'Ambient light sensors detect surrounding light levels and automatically adjust screen brightness for optimal viewing and battery conservation.', 22, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('e6a7f8b9-0123-45de-5678-7abcdef89012', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'What is the typical pin count for DDR4 SODIMM modules?', '["184 pins", "204 pins", "240 pins", "260 pins"]', 1, 'DDR4 SODIMM modules have 204 pins, while DDR5 SODIMM modules have 260 pins. Desktop DIMM modules have different pin counts.', 23, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('f7b8a9c0-1234-56ef-6789-8abcdef90123', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Which type of laptop display panel offers the fastest response times but has limited viewing angles?', '["IPS", "VA", "TN", "OLED"]', 2, 'TN (Twisted Nematic) panels provide fast response times ideal for gaming but have poor viewing angles and color reproduction compared to IPS panels.', 24, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('a8c9b0d1-2345-67fa-7890-9abcdef01234', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'A laptop user wants to connect two external monitors. Which connection type would be most suitable for this setup?', '["VGA splitter", "USB-C with DisplayPort Alt Mode", "HDMI switch", "Serial port"]', 1, 'USB-C with DisplayPort Alt Mode can support multiple monitors through daisy-chaining or using a dock/hub, providing the bandwidth needed for dual monitor setups.', 25, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z');

-- Insert Text Content (order 26-27)
INSERT INTO lesson_texts (id, lesson_id, text, order_index, created_at, updated_at) VALUES
('e0b1f2a3-4567-89de-f012-0abcdef12345', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Understanding laptop hardware, displays, and features is essential for CompTIA A+ certification. Key exam topics include memory types (SODIMM), storage interfaces (M.2 NVMe vs SATA), display technologies (LCD, OLED, touch), wireless standards, power management, and common troubleshooting scenarios. Focus on the differences between laptop and desktop components, as well as the integrated nature of laptop systems that affects repair and upgrade options.', 26, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z'),
('f1c2a3b4-5678-90ef-0123-1abcdef23456', '4771cdf2-fa08-44c7-8d07-54d9b2f9280e', 'Practice identifying laptop-specific hardware by form factor and connector types. Remember that laptops prioritize mobility, battery life, and thermal efficiency over raw performance, leading to design choices that impact serviceability and upgrade paths. This foundational knowledge will help you succeed on the CompTIA A+ Core 1 exam and in real-world laptop support scenarios.', 27, '2025-08-05T12:00:00Z', '2025-08-05T12:00:00Z');

